import { useMemo,useState } from 'react';import { Section } from '../components/Section';import { Seo } from '../components/Seo';function calc(p:number,r:number,n:number){const m=r/12/100;const emi=m===0?p/n:(p*m*Math.pow(1+m,n))/(Math.pow(1+m,n)-1);return{emi:Math.round(emi||0),interest:Math.round((emi||0)*n-p),total:Math.round((emi||0)*n)}}export function EmiCalculator(){const [amount,setAmount]=useState(500000),[rate,setRate]=useState(11.5),[tenure,setTenure]=useState(60);const r=useMemo(()=>calc(amount,rate,tenure),[amount,rate,tenure]);return <><Seo title="EMI Calculator" description="Accurate EMI calculator for Indian loans."/><Section><h1 className="text-5xl font-black">EMI Calculator</h1><div className="mt-8 grid gap-8 md:grid-cols-2"><div className="card space-y-4"><label>Loan Amount<input className="input" type="number" value={amount} onChange={e=>setAmount(+e.target.value)}/></label><label>Interest Rate (%)<input className="input" type="number" value={rate} onChange={e=>setRate(+e.target.value)}/></label><label>Loan Tenure (months)<input className="input" type="number" value={tenure} onChange={e=>setTenure(+e.target.value)}/></label></div><div className="card"><p>Monthly EMI</p><h2 className="text-5xl font-black text-brand-red">₹{r.emi.toLocaleString('en-IN')}</h2><p className="mt-6">Interest: ₹{r.interest.toLocaleString('en-IN')}</p><p>Total Amount: ₹{r.total.toLocaleString('en-IN')}</p></div></div></Section></>}
